insert into public.gjm_chatbot_faqs (id, category, question_en, answer_en, question_hi, answer_hi, keywords, related_questions, updated_at, published) values
(1, 'General Event Information', 'What is Geeta Jayanti Mahotsav?', 'Geeta Jayanti Mahotsav is an educational and cultural event organized to celebrate the teachings and importance of the Bhagavad Gita. It encourages students to learn about Indian culture, spirituality, moral values and the timeless teachings of Lord Krishna through different competitions and activities.', 'गीता जयंती महोत्सव क्या है?', 'गीता जयंती महोत्सव एक शैक्षणिक और सांस्कृतिक आयोजन है, जिसका उद्देश्य श्रीमद्भगवद्गीता की शिक्षाओं और महत्व का प्रचार करना है। इसके माध्यम से विद्यार्थियों को भारतीय संस्कृति, आध्यात्मिकता, नैतिक मूल्यों और भगवान श्रीकृष्ण के उपदेशों को समझने का अवसर मिलता है।', '["what", "geeta", "jayanti", "mahotsav", "educational", "and", "cultural", "event", "organized", "celebrate", "the", "teachings", "importance", "bhagavad", "gita", "encourages", "students", "learn", "about", "indian", "culture", "spirituality", "moral", "values", "timeless", "lord", "krishna", "through", "different", "competitions", "activities", "गीता", "जयंती", "महोत्सव", "एक", "शैक्षणिक", "और", "सांस्कृतिक", "आयोजन", "है", "जिसका", "उद्देश्य", "श्रीमद्भगवद्गीता", "की", "शिक्षाओं", "महत्व", "का", "प्रचार", "करना", "है।", "इसके", "माध्यम", "से", "विद्यार्थियों", "को", "भारतीय", "संस्कृति", "आध्यात्मिकता", "नैतिक", "मूल्यों", "भगवान", "श्रीकृष्ण", "के", "उपदेशों", "समझने", "अवसर", "मिलता"]'::jsonb, '[2, 3]'::jsonb, '2026-11-01', true),
(2, 'General Event Information', 'When will Geeta Jayanti Mahotsav 2026 be organized?', 'Geeta Jayanti Mahotsav 2026 is scheduled for 20 December 2026. Please check the official website for the latest program schedule and announcements.', 'गीता जयंती महोत्सव 2026 कब आयोजित होगा?', 'गीता जयंती महोत्सव 2026 का आयोजन 20 दिसंबर 2026 को निर्धारित है। कार्यक्रम की समय-सारणी और नवीनतम घोषणाओं के लिए आधिकारिक वेबसाइट देखते रहें।', '["when", "will", "geeta", "jayanti", "mahotsav", "organized", "scheduled", "for", "december", "please", "check", "the", "official", "website", "latest", "program", "schedule", "and", "announcements", "गीता", "जयंती", "महोत्सव", "का", "आयोजन", "दिसंबर", "को", "निर्धारित", "है।", "कार्यक्रम", "की", "समय", "सारणी", "और", "नवीनतम", "घोषणाओं", "के", "लिए", "आधिकारिक", "वेबसाइट", "देखते", "रहें।", "mahotsav kab", "event kab", "event date"]'::jsonb, '[1, 3, 4]'::jsonb, '2026-11-01', true),
(3, 'General Event Information', 'What is the main objective of this event?', 'The main objective is to spread the teachings of the Bhagavad Gita among students, encourage cultural awareness, develop confidence and provide opportunities to showcase knowledge and creativity.', 'इस आयोजन का मुख्य उद्देश्य क्या है?', 'इस आयोजन का मुख्य उद्देश्य विद्यार्थियों तक श्रीमद्भगवद्गीता की शिक्षाओं को पहुँचाना, सांस्कृतिक जागरूकता बढ़ाना, आत्मविश्वास विकसित करना और ज्ञान एवं रचनात्मकता प्रदर्शित करने का अवसर प्रदान करना है।', '["what", "the", "main", "objective", "this", "event", "spread", "teachings", "bhagavad", "gita", "among", "students", "encourage", "cultural", "awareness", "develop", "confidence", "and", "provide", "opportunities", "showcase", "knowledge", "creativity", "इस", "आयोजन", "का", "मुख्य", "उद्देश्य", "विद्यार्थियों", "तक", "श्रीमद्भगवद्गीता", "की", "शिक्षाओं", "को", "पहुँचाना", "सांस्कृतिक", "जागरूकता", "बढ़ाना", "आत्मविश्वास", "विकसित", "करना", "और", "ज्ञान", "एवं", "रचनात्मकता", "प्रदर्शित", "करने", "अवसर", "प्रदान", "है।"]'::jsonb, '[1, 2, 4, 5]'::jsonb, '2026-11-01', true),
(4, 'General Event Information', 'Who can participate in the event?', 'Students who meet the eligibility requirements mentioned in the official competition rules can participate. Please check the eligibility and age-group guidelines before registering.', 'इस आयोजन में कौन भाग ले सकता है?', 'आधिकारिक प्रतियोगिता नियमों में निर्धारित पात्रता पूरी करने वाले विद्यार्थी भाग ले सकते हैं। पंजीकरण से पहले आयु वर्ग और पात्रता संबंधी दिशा-निर्देश अवश्य जाँच लें।', '["who", "can", "participate", "the", "event", "students", "meet", "eligibility", "requirements", "mentioned", "official", "competition", "rules", "please", "check", "and", "age", "group", "guidelines", "before", "registering", "आधिकारिक", "प्रतियोगिता", "नियमों", "में", "निर्धारित", "पात्रता", "पूरी", "करने", "वाले", "विद्यार्थी", "भाग", "ले", "सकते", "हैं।", "पंजीकरण", "से", "पहले", "आयु", "वर्ग", "और", "संबंधी", "दिशा", "निर्देश", "अवश्य", "जाँच", "लें।"]'::jsonb, '[2, 3, 5, 6]'::jsonb, '2026-11-01', true),
(5, 'General Event Information', 'Is participation free?', 'Please check the official registration page for the latest participation fee information. If no fee is mentioned, contact the event support team for confirmation.', 'क्या भागीदारी निःशुल्क है?', 'भागीदारी शुल्क की जानकारी के लिए आधिकारिक पंजीकरण पेज देखें। यदि शुल्क का उल्लेख नहीं है, तो पुष्टि के लिए आयोजन की सहायता टीम से संपर्क करें।', '["participation", "free", "please", "check", "the", "official", "registration", "page", "for", "latest", "fee", "information", "mentioned", "contact", "event", "support", "team", "confirmation", "भागीदारी", "शुल्क", "की", "जानकारी", "के", "लिए", "आधिकारिक", "पंजीकरण", "पेज", "देखें।", "यदि", "का", "उल्लेख", "नहीं", "है", "तो", "पुष्टि", "आयोजन", "सहायता", "टीम", "से", "संपर्क", "करें।"]'::jsonb, '[3, 4, 6, 7]'::jsonb, '2026-11-01', true),
(6, 'General Event Information', 'Can students from different states participate?', 'Students from different states can participate if they satisfy the official eligibility conditions. Select your correct state and district during registration.', 'क्या अलग-अलग राज्यों के विद्यार्थी भाग ले सकते हैं?', 'विभिन्न राज्यों के विद्यार्थी आधिकारिक पात्रता शर्तें पूरी करने पर भाग ले सकते हैं। पंजीकरण करते समय अपना सही राज्य और जिला चुनें।', '["can", "students", "from", "different", "states", "participate", "they", "satisfy", "the", "official", "eligibility", "conditions", "select", "your", "correct", "state", "and", "district", "during", "registration", "विभिन्न", "राज्यों", "के", "विद्यार्थी", "आधिकारिक", "पात्रता", "शर्तें", "पूरी", "करने", "पर", "भाग", "ले", "सकते", "हैं।", "पंजीकरण", "करते", "समय", "अपना", "सही", "राज्य", "और", "जिला", "चुनें।"]'::jsonb, '[4, 5, 7, 8]'::jsonb, '2026-11-01', true),
(7, 'General Event Information', 'Which competitions are available?', 'There are four competitions: Shlok Uccharan, Rashtriya Geet Quiz, Digital Bhashan and Drawing Competition. Check the competition section for detailed rules.', 'कौन-कौन सी प्रतियोगिताएँ उपलब्ध हैं?', 'इस आयोजन में चार प्रतियोगिताएँ हैं: श्लोक उच्चारण, राष्ट्रीय गीत क्विज़, डिजिटल भाषण और चित्रकला प्रतियोगिता। विस्तृत नियमों के लिए प्रतियोगिता अनुभाग देखें।', '["which", "competitions", "are", "available", "there", "four", "shlok", "uccharan", "rashtriya", "geet", "quiz", "digital", "bhashan", "and", "drawing", "competition", "check", "the", "section", "for", "detailed", "rules", "इस", "आयोजन", "में", "चार", "प्रतियोगिताएँ", "हैं", "श्लोक", "उच्चारण", "राष्ट्रीय", "गीत", "क्विज़", "डिजिटल", "भाषण", "और", "चित्रकला", "प्रतियोगिता।", "विस्तृत", "नियमों", "के", "लिए", "प्रतियोगिता", "अनुभाग", "देखें।"]'::jsonb, '[5, 6, 8, 9]'::jsonb, '2026-11-01', true),
(8, 'General Event Information', 'Can I participate in multiple competitions?', 'Participation in multiple competitions depends on the official participation rules. Please check the competition guidelines or contact support before submitting multiple entries.', 'क्या मैं एक से अधिक प्रतियोगिताओं में भाग ले सकता/सकती हूँ?', 'एक से अधिक प्रतियोगिताओं में भाग लेने की अनुमति आधिकारिक नियमों पर निर्भर करती है। कई प्रतियोगिताओं में आवेदन करने से पहले दिशा-निर्देश देखें या सहायता टीम से संपर्क करें।', '["can", "participate", "multiple", "competitions", "participation", "depends", "the", "official", "rules", "please", "check", "competition", "guidelines", "contact", "support", "before", "submitting", "entries", "एक", "से", "अधिक", "प्रतियोगिताओं", "में", "भाग", "लेने", "की", "अनुमति", "आधिकारिक", "नियमों", "पर", "निर्भर", "करती", "है।", "कई", "आवेदन", "करने", "पहले", "दिशा", "निर्देश", "देखें", "या", "सहायता", "टीम", "संपर्क", "करें।"]'::jsonb, '[6, 7, 9, 10]'::jsonb, '2026-11-01', true),
(9, 'General Event Information', 'Is the event online or offline?', 'The website supports online registration and digital participation activities. Please refer to the official event schedule for details about any offline programs.', 'आयोजन ऑनलाइन है या ऑफलाइन?', 'वेबसाइट पर ऑनलाइन पंजीकरण और डिजिटल भागीदारी की सुविधाएँ उपलब्ध हैं। ऑफलाइन कार्यक्रमों की जानकारी के लिए आधिकारिक कार्यक्रम-सूची देखें।', '["the", "event", "online", "offline", "website", "supports", "registration", "and", "digital", "participation", "activities", "please", "refer", "official", "schedule", "for", "details", "about", "any", "programs", "वेबसाइट", "पर", "ऑनलाइन", "पंजीकरण", "और", "डिजिटल", "भागीदारी", "की", "सुविधाएँ", "उपलब्ध", "हैं।", "ऑफलाइन", "कार्यक्रमों", "जानकारी", "के", "लिए", "आधिकारिक", "कार्यक्रम", "सूची", "देखें।"]'::jsonb, '[7, 8, 10, 11]'::jsonb, '2026-11-01', true),
(10, 'General Event Information', 'Where can I get official updates?', 'For official event updates, check the Geeta Jayanti Mahotsav website and its announcements section. For personal assistance, use Contact Support to reach the organizers.', 'आधिकारिक अपडेट कहाँ मिलेंगे?', 'आधिकारिक अपडेट के लिए गीता जयंती महोत्सव की वेबसाइट और घोषणा अनुभाग देखें। सहायता के लिए संपर्क विवरण नीचे दिए गए हैं।', '["where", "can", "get", "official", "updates", "you", "through", "the", "geeta", "jayanti", "mahotsav", "website", "and", "its", "announcements", "section", "आप", "गीता", "जयंती", "महोत्सव", "की", "आधिकारिक", "वेबसाइट", "और", "घोषणा", "अनुभाग", "के", "माध्यम", "से", "नवीनतम", "जानकारी", "प्राप्त", "कर", "सकते", "हैं।"]'::jsonb, '[8, 9, 11, 12]'::jsonb, '2026-11-01', true),
(11, 'Registration And Account', 'How can I register for Geeta Jayanti Mahotsav?', 'Visit the official website and click on the Registration option. Sign in using your email or Google account, complete the required personal details, upload the requested documents and submit the registration form. Follow the on-screen instructions to complete the process.', 'गीता जयंती महोत्सव के लिए पंजीकरण कैसे करें?', 'आधिकारिक वेबसाइट पर जाएँ और Registration विकल्प पर क्लिक करें। अपने ईमेल या Google अकाउंट से लॉगिन करें। आवश्यक व्यक्तिगत जानकारी भरें, माँगे गए दस्तावेज अपलोड करें और पंजीकरण फॉर्म सबमिट करें।', '["how", "can", "register", "for", "geeta", "jayanti", "mahotsav", "visit", "the", "official", "website", "and", "click", "registration", "option", "sign", "using", "your", "email", "google", "account", "complete", "required", "personal", "details", "upload", "requested", "documents", "submit", "form", "follow", "screen", "instructions", "process", "आधिकारिक", "वेबसाइट", "पर", "जाएँ", "और", "विकल्प", "क्लिक", "करें।", "अपने", "ईमेल", "या", "अकाउंट", "से", "लॉगिन", "आवश्यक", "व्यक्तिगत", "जानकारी", "भरें", "माँगे", "गए", "दस्तावेज", "अपलोड", "करें", "पंजीकरण", "फॉर्म", "सबमिट", "registration kaise", "register kaise", "mera registration", "panjeekaran"]'::jsonb, '[9, 10, 12, 13]'::jsonb, '2026-11-01', true),
(12, 'Registration And Account', 'How can I create a student account?', 'Open the website, select Sign Up or Registration and enter your email address and other requested information. Complete the email verification process and follow the instructions to access your student account.', 'विद्यार्थी खाता कैसे बनाएँ?', 'वेबसाइट खोलें और Sign Up या Registration विकल्प चुनें। अपना ईमेल और आवश्यक जानकारी दर्ज करें। ईमेल सत्यापन पूरा करें और निर्देशों का पालन करके अपना विद्यार्थी अकाउंट बनाएँ।', '["how", "can", "create", "student", "account", "open", "the", "website", "select", "sign", "registration", "and", "enter", "your", "email", "address", "other", "requested", "information", "complete", "verification", "process", "follow", "instructions", "access", "वेबसाइट", "खोलें", "और", "या", "विकल्प", "चुनें।", "अपना", "ईमेल", "आवश्यक", "जानकारी", "दर्ज", "करें।", "सत्यापन", "पूरा", "करें", "निर्देशों", "का", "पालन", "करके", "विद्यार्थी", "अकाउंट", "बनाएँ।"]'::jsonb, '[10, 11, 13, 14]'::jsonb, '2026-11-01', true),
(13, 'Registration And Account', 'Is email verification mandatory?', 'Email verification is required wherever the registration or authentication process requests it. It helps confirm that you have access to your registered email address.', 'क्या ईमेल सत्यापन अनिवार्य है?', 'जहाँ पंजीकरण या लॉगिन प्रक्रिया में ईमेल सत्यापन आवश्यक है, वहाँ इसे पूरा करना अनिवार्य है। इससे यह सुनिश्चित होता है कि आपका पंजीकृत ईमेल सही है।', '["email", "verification", "mandatory", "required", "wherever", "the", "registration", "authentication", "process", "requests", "helps", "confirm", "that", "you", "have", "access", "your", "registered", "address", "जहाँ", "पंजीकरण", "या", "लॉगिन", "प्रक्रिया", "में", "ईमेल", "सत्यापन", "आवश्यक", "है", "वहाँ", "इसे", "पूरा", "करना", "अनिवार्य", "है।", "इससे", "यह", "सुनिश्चित", "होता", "कि", "आपका", "पंजीकृत", "सही"]'::jsonb, '[11, 12, 14, 15]'::jsonb, '2026-11-01', true),
(14, 'Registration And Account', 'How can I verify my email using OTP?', 'Enter your email address and request an OTP. Check your inbox, enter the received verification code in the website and complete the verification process.', 'OTP से ईमेल सत्यापन कैसे करें?', 'अपना ईमेल दर्ज करें और OTP प्राप्त करने का विकल्प चुनें। अपने इनबॉक्स में आया OTP वेबसाइट पर दर्ज करें और ईमेल सत्यापन पूरा करें।', '["how", "can", "verify", "email", "using", "otp", "enter", "your", "address", "and", "request", "check", "inbox", "the", "received", "verification", "code", "website", "complete", "process", "अपना", "ईमेल", "दर्ज", "करें", "और", "प्राप्त", "करने", "का", "विकल्प", "चुनें।", "अपने", "इनबॉक्स", "में", "आया", "वेबसाइट", "पर", "सत्यापन", "पूरा", "करें।"]'::jsonb, '[12, 13, 15, 16]'::jsonb, '2026-11-01', true),
(15, 'Registration And Account', 'I have not received my OTP. What should I do?', 'First, check your spam, junk and promotions folders. Verify that your email address is correct. Wait for a short time and use the Resend OTP option if available. Avoid requesting too many OTPs within a short period. If the problem continues, contact technical support.', 'मुझे OTP नहीं मिला। क्या करूँ?', 'सबसे पहले अपना Spam, Junk और Promotions फोल्डर चेक करें। सुनिश्चित करें कि ईमेल सही दर्ज किया गया है। कुछ समय प्रतीक्षा करें और उपलब्ध होने पर Resend OTP विकल्प का उपयोग करें। समस्या जारी रहने पर तकनीकी सहायता से संपर्क करें।', '["have", "not", "received", "otp", "what", "should", "first", "check", "your", "spam", "junk", "and", "promotions", "folders", "verify", "that", "email", "address", "correct", "wait", "for", "short", "time", "use", "the", "resend", "option", "available", "avoid", "requesting", "too", "many", "otps", "within", "period", "problem", "continues", "contact", "technical", "support", "सबसे", "पहले", "अपना", "और", "फोल्डर", "चेक", "करें।", "सुनिश्चित", "करें", "कि", "ईमेल", "सही", "दर्ज", "किया", "गया", "है।", "कुछ", "समय", "प्रतीक्षा", "उपलब्ध", "होने", "पर", "विकल्प", "का", "उपयोग", "समस्या", "जारी", "रहने", "तकनीकी", "सहायता", "से", "संपर्क", "otp nahi aa raha", "otp nahi aaya", "nahi mil raha", "resend otp", "otp karun", "nahi", "raha", "karun"]'::jsonb, '[13, 14, 16, 17]'::jsonb, '2026-11-01', true),
(16, 'Registration And Account', 'Can I register using Google Login?', 'Yes, if Google Login is enabled on the website, you can select Continue with Google and choose your Google account. Complete any additional verification or registration details requested by the website.', 'क्या Google Login से पंजीकरण कर सकते हैं?', 'हाँ, यदि वेबसाइट पर Google Login उपलब्ध है, तो Continue with Google पर क्लिक करके अपना Google अकाउंट चुनें। वेबसाइट द्वारा माँगी गई अतिरिक्त जानकारी और सत्यापन पूरा करें।', '["can", "register", "using", "google", "login", "yes", "enabled", "the", "website", "you", "select", "continue", "with", "and", "choose", "your", "account", "complete", "any", "additional", "verification", "registration", "details", "requested", "हाँ", "यदि", "वेबसाइट", "पर", "उपलब्ध", "है", "तो", "क्लिक", "करके", "अपना", "अकाउंट", "चुनें।", "द्वारा", "माँगी", "गई", "अतिरिक्त", "जानकारी", "और", "सत्यापन", "पूरा", "करें।"]'::jsonb, '[14, 15, 17, 18]'::jsonb, '2026-11-01', true),
(17, 'Registration And Account', 'Can I register using my email and password?', 'If email and password registration is enabled, you can create your account using your email address and password. Complete the required verification steps before accessing your account.', 'क्या ईमेल और पासवर्ड से पंजीकरण कर सकते हैं?', 'यदि ईमेल और पासवर्ड से पंजीकरण की सुविधा उपलब्ध है, तो आप अपने ईमेल और पासवर्ड से अकाउंट बना सकते हैं। अकाउंट इस्तेमाल करने से पहले आवश्यक सत्यापन पूरा करें।', '["can", "register", "using", "email", "and", "password", "registration", "enabled", "you", "create", "your", "account", "address", "complete", "the", "required", "verification", "steps", "before", "accessing", "यदि", "ईमेल", "और", "पासवर्ड", "से", "पंजीकरण", "की", "सुविधा", "उपलब्ध", "है", "तो", "आप", "अपने", "अकाउंट", "बना", "सकते", "हैं।", "इस्तेमाल", "करने", "पहले", "आवश्यक", "सत्यापन", "पूरा", "करें।"]'::jsonb, '[15, 16, 18, 19]'::jsonb, '2026-11-01', true),
(18, 'Registration And Account', 'Can I edit my registration details?', 'If the website provides an Edit Profile or Edit Registration option, you can update the permitted details. For locked or submitted information, contact the event support team for assistance.', 'क्या पंजीकरण की जानकारी में बदलाव कर सकता/सकती हूँ?', 'यदि वेबसाइट पर Edit Profile या Edit Registration विकल्प उपलब्ध है, तो आप अनुमत जानकारी बदल सकते हैं। लॉक की गई या सबमिट की गई जानकारी में बदलाव के लिए सहायता टीम से संपर्क करें।', '["can", "edit", "registration", "details", "the", "website", "provides", "profile", "option", "you", "update", "permitted", "for", "locked", "submitted", "information", "contact", "event", "support", "team", "assistance", "यदि", "वेबसाइट", "पर", "या", "विकल्प", "उपलब्ध", "है", "तो", "आप", "अनुमत", "जानकारी", "बदल", "सकते", "हैं।", "लॉक", "की", "गई", "सबमिट", "में", "बदलाव", "के", "लिए", "सहायता", "टीम", "से", "संपर्क", "करें।"]'::jsonb, '[16, 17, 19, 20]'::jsonb, '2026-11-01', true),
(19, 'Registration And Account', 'Can I register more than once?', 'Please avoid creating duplicate registrations. Use your existing account to access your registration. If you have accidentally submitted duplicate forms, contact the support team.', 'क्या एक से अधिक बार पंजीकरण कर सकता/सकती हूँ?', 'कृपया एक से अधिक बार पंजीकरण न करें। अपने मौजूदा अकाउंट से ही पंजीकरण देखें। यदि गलती से दो बार फॉर्म सबमिट हो गया है, तो सहायता टीम से संपर्क करें।', '["can", "register", "more", "than", "once", "please", "avoid", "creating", "duplicate", "registrations", "use", "your", "existing", "account", "access", "registration", "you", "have", "accidentally", "submitted", "forms", "contact", "the", "support", "team", "कृपया", "एक", "से", "अधिक", "बार", "पंजीकरण", "करें।", "अपने", "मौजूदा", "अकाउंट", "ही", "देखें।", "यदि", "गलती", "दो", "फॉर्म", "सबमिट", "हो", "गया", "है", "तो", "सहायता", "टीम", "संपर्क"]'::jsonb, '[17, 18, 20, 21]'::jsonb, '2026-11-01', true),
(20, 'Registration And Account', 'How can I confirm that my registration is successful?', 'After submitting the registration form, check the confirmation message and your student dashboard. If the registration status shows completed or approved, follow any further instructions displayed there.', 'पंजीकरण सफल हुआ है, इसकी पुष्टि कैसे करें?', 'पंजीकरण फॉर्म सबमिट करने के बाद कन्फर्मेशन मैसेज और अपना स्टूडेंट डैशबोर्ड चेक करें। यदि पंजीकरण की स्थिति Completed या Approved दिखाई देती है, तो आगे दिए गए निर्देशों का पालन करें।', '["how", "can", "confirm", "that", "registration", "successful", "after", "submitting", "the", "form", "check", "confirmation", "message", "and", "your", "student", "dashboard", "status", "shows", "completed", "approved", "follow", "any", "further", "instructions", "displayed", "there", "पंजीकरण", "फॉर्म", "सबमिट", "करने", "के", "बाद", "कन्फर्मेशन", "मैसेज", "और", "अपना", "स्टूडेंट", "डैशबोर्ड", "चेक", "करें।", "यदि", "की", "स्थिति", "या", "दिखाई", "देती", "है", "तो", "आगे", "दिए", "गए", "निर्देशों", "का", "पालन"]'::jsonb, '[18, 19, 21, 22]'::jsonb, '2026-11-01', true),
(21, 'Personal Details And Documents', 'What information is required during registration?', 'You may be asked to provide your name, email address, mobile number, date of birth, state, district, complete address, bank details and other information required by the official registration form.', 'पंजीकरण के समय कौन-सी जानकारी देनी होगी?', 'पंजीकरण के दौरान आपसे नाम, ईमेल, मोबाइल नंबर, जन्मतिथि, राज्य, जिला, पूरा पता, बैंक संबंधी जानकारी और फॉर्म में माँगी गई अन्य जानकारी ली जा सकती है।', '["what", "information", "required", "during", "registration", "you", "may", "asked", "provide", "your", "name", "email", "address", "mobile", "number", "date", "birth", "state", "district", "complete", "bank", "details", "and", "other", "the", "official", "form", "पंजीकरण", "के", "दौरान", "आपसे", "नाम", "ईमेल", "मोबाइल", "नंबर", "जन्मतिथि", "राज्य", "जिला", "पूरा", "पता", "बैंक", "संबंधी", "जानकारी", "और", "फॉर्म", "में", "माँगी", "गई", "अन्य", "ली", "जा", "सकती", "है।"]'::jsonb, '[19, 20, 22, 23]'::jsonb, '2026-11-01', true),
(22, 'Personal Details And Documents', 'Why is my mobile number required?', 'Your mobile number may be used for important event communication, registration assistance and participant-related updates. Provide an active and correct mobile number.', 'मोबाइल नंबर क्यों आवश्यक है?', 'आपके मोबाइल नंबर का उपयोग आयोजन से संबंधित महत्वपूर्ण सूचनाओं, पंजीकरण सहायता और अन्य अपडेट के लिए किया जा सकता है। कृपया सक्रिय और सही नंबर दर्ज करें।', '["why", "mobile", "number", "required", "your", "may", "used", "for", "important", "event", "communication", "registration", "assistance", "and", "participant", "related", "updates", "provide", "active", "correct", "आपके", "मोबाइल", "नंबर", "का", "उपयोग", "आयोजन", "से", "संबंधित", "महत्वपूर्ण", "सूचनाओं", "पंजीकरण", "सहायता", "और", "अन्य", "अपडेट", "के", "लिए", "किया", "जा", "सकता", "है।", "कृपया", "सक्रिय", "सही", "दर्ज", "करें।"]'::jsonb, '[20, 21, 23, 24]'::jsonb, '2026-11-01', true),
(23, 'Personal Details And Documents', 'Why do I need to select my state and district?', 'State and district information helps organize participant records and identify the location of registered students. Please select the correct information.', 'राज्य और जिला क्यों चुनना है?', 'राज्य और जिले की जानकारी से प्रतिभागियों का रिकॉर्ड व्यवस्थित रखने और उनकी स्थान संबंधी जानकारी पहचानने में सहायता मिलती है। कृपया सही जानकारी चुनें।', '["why", "need", "select", "state", "and", "district", "information", "helps", "organize", "participant", "records", "identify", "the", "location", "registered", "students", "please", "correct", "राज्य", "और", "जिले", "की", "जानकारी", "से", "प्रतिभागियों", "का", "रिकॉर्ड", "व्यवस्थित", "रखने", "उनकी", "स्थान", "संबंधी", "पहचानने", "में", "सहायता", "मिलती", "है।", "कृपया", "सही", "चुनें।"]'::jsonb, '[21, 22, 24, 25]'::jsonb, '2026-11-01', true),
(24, 'Personal Details And Documents', 'How does district selection work?', 'First select your state from the dropdown menu. The district dropdown will then display the districts associated with the selected state. Choose your correct district.', 'जिला चुनने की प्रक्रिया कैसे काम करती है?', 'सबसे पहले ड्रॉपडाउन से अपना राज्य चुनें। इसके बाद जिला ड्रॉपडाउन में उस राज्य के जिले दिखाई देंगे। उनमें से अपना सही जिला चुनें।', '["how", "does", "district", "selection", "work", "first", "select", "your", "state", "from", "the", "dropdown", "menu", "will", "then", "display", "districts", "associated", "with", "selected", "choose", "correct", "सबसे", "पहले", "ड्रॉपडाउन", "से", "अपना", "राज्य", "चुनें।", "इसके", "बाद", "जिला", "में", "उस", "के", "जिले", "दिखाई", "देंगे।", "उनमें", "सही"]'::jsonb, '[22, 23, 25, 26]'::jsonb, '2026-11-01', true),
(25, 'Personal Details And Documents', 'Why are bank account details required?', 'Bank details may be collected for official event-related administrative purposes or eligible prize disbursement, depending on the event policy. Enter accurate details and refer to the official privacy notice.', 'बैंक खाते का विवरण क्यों माँगा जाता है?', 'आयोजन की नीति के अनुसार बैंक विवरण आधिकारिक प्रशासनिक कार्यों या पात्र विजेताओं को पुरस्कार राशि देने के लिए एकत्र किए जा सकते हैं। सही जानकारी भरें और आधिकारिक गोपनीयता नीति देखें।', '["why", "are", "bank", "account", "details", "required", "may", "collected", "for", "official", "event", "related", "administrative", "purposes", "eligible", "prize", "disbursement", "depending", "the", "policy", "enter", "accurate", "and", "refer", "privacy", "notice", "आयोजन", "की", "नीति", "के", "अनुसार", "बैंक", "विवरण", "आधिकारिक", "प्रशासनिक", "कार्यों", "या", "पात्र", "विजेताओं", "को", "पुरस्कार", "राशि", "देने", "लिए", "एकत्र", "किए", "जा", "सकते", "हैं।", "सही", "जानकारी", "भरें", "और", "गोपनीयता", "देखें।"]'::jsonb, '[23, 24, 26, 27]'::jsonb, '2026-11-01', true),
(26, 'Personal Details And Documents', 'How should I enter my IFSC code?', 'Enter the correct 11-character IFSC code associated with your bank branch. Double-check the code before submitting the form.', 'IFSC कोड कैसे दर्ज करें?', 'अपने बैंक की शाखा से संबंधित सही 11 अक्षरों वाला IFSC कोड दर्ज करें। फॉर्म सबमिट करने से पहले कोड दोबारा जाँच लें।', '["how", "should", "enter", "ifsc", "code", "the", "correct", "character", "associated", "with", "your", "bank", "branch", "double", "check", "before", "submitting", "form", "अपने", "बैंक", "की", "शाखा", "से", "संबंधित", "सही", "अक्षरों", "वाला", "कोड", "दर्ज", "करें।", "फॉर्म", "सबमिट", "करने", "पहले", "दोबारा", "जाँच", "लें।"]'::jsonb, '[24, 25, 27, 28]'::jsonb, '2026-11-01', true),
(27, 'Personal Details And Documents', 'What format should my photograph be in?', 'Upload your photograph in one of the file formats and within the size limits accepted by the registration form. Check the upload instructions displayed on the website.', 'फोटो किस फ़ॉर्मेट में होनी चाहिए?', 'अपनी फोटो उसी फाइल फॉर्मेट और निर्धारित साइज में अपलोड करें जिसे पंजीकरण फॉर्म स्वीकार करता है। वेबसाइट पर दिए गए अपलोड निर्देश देखें।', '["what", "format", "should", "photograph", "upload", "your", "one", "the", "file", "formats", "and", "within", "size", "limits", "accepted", "registration", "form", "check", "instructions", "displayed", "website", "अपनी", "फोटो", "उसी", "फाइल", "फॉर्मेट", "और", "निर्धारित", "साइज", "में", "अपलोड", "करें", "जिसे", "पंजीकरण", "फॉर्म", "स्वीकार", "करता", "है।", "वेबसाइट", "पर", "दिए", "गए", "निर्देश", "देखें।"]'::jsonb, '[25, 26, 28, 29]'::jsonb, '2026-11-01', true),
