-- Geeta Jayanti chatbot FAQ knowledge base. Safe to reapply.
create table if not exists public.gjm_chatbot_faqs (
  id integer primary key check (id between 1 and 80),
  category text not null, question_en text not null, answer_en text not null,
  question_hi text not null, answer_hi text not null, keywords jsonb not null default '[]'::jsonb,
  related_questions jsonb not null default '[]'::jsonb, updated_at date not null default current_date,
  published boolean not null default true
);
alter table public.gjm_chatbot_faqs enable row level security;
drop policy if exists "Anyone can read published chatbot FAQs" on public.gjm_chatbot_faqs;
create policy "Anyone can read published chatbot FAQs" on public.gjm_chatbot_faqs for select to anon, authenticated using (published or public.current_user_role() = 'admin');
drop policy if exists "Admins manage chatbot FAQs" on public.gjm_chatbot_faqs;
create policy "Admins manage chatbot FAQs" on public.gjm_chatbot_faqs for all to authenticated using (public.current_user_role() = 'admin') with check (public.current_user_role() = 'admin');
grant select on public.gjm_chatbot_faqs to anon, authenticated;
grant insert, update, delete on public.gjm_chatbot_faqs to authenticated;
on conflict (id) do nothing;
